input.command:
cd /workspace/dataset
rep() { local n=$1 c=$2 s=""; for ((i=0;i<n;i++)); do s+="$c"; done; printf '%s' "$s"; }
# multi-label totalling near 255/256
mk(){ local total=$1; local s=""; while [ ${#s} -lt $total ]; do s+="ab."; done; printf '%s' "${s:0:$total}"; }
for n in 253 254 255 256 257; do d=$(mk $n); printf 'multilabel %s B tail=%-4s -> %s\n' "$(printf '%s' "$d"|wc -c)" "$(printf '%s' "$d"|tail -c 4)" "$(./test4_executable "$d"|tr '\n' ' ')"; done
